 439→    #[test]
 440→    fn capabilities_can_service() {
 441→        let caps = ConnectorCapabilities {
 442→            supported_target_kinds: vec![TargetKind::Wallet, TargetKind::Program],
 443→            supported_modes: vec![TargetMode::Backfill],
 444→            chain_family: ChainFamily::Solana,
 445→        };
 446→
 447→        let wallet_target = make_target(
 448→            TargetKind::Wallet,
 449→            ChainFamily::Solana,
 450→            Some("abc"),
 451→            None,
 452→            TargetMode::Backfill,
 453→        );
 454→        assert!(caps.can_service(&wallet_target));
 455→
 456→        let evm_wallet = make_target(
 457→            TargetKind::Wallet,
 458→            ChainFamily::Evm,
 459→            Some("0xabc"),
