 463→        assert!(!caps.can_service(&evm_wallet)); // wrong chain family
 464→
 465→        let contract = make_target(
 466→            TargetKind::Contract,
 467→            ChainFamily::Solana,
 468→            Some("0xabc"),
 469→            None,
 470→            TargetMode::Backfill,
 471→        );
 472→        assert!(!caps.can_service(&contract)); // unsupported kind
 473→    }
