 570→    pub async fn get_matches_by_target(
 571→        &self,
 572→        target_id: Uuid,
 573→        limit: i64,
 574→        offset: i64,
 575→    ) -> anyhow::Result<Vec<(TargetMatch, RawTransaction)>> {
 576→        let rows = sqlx::query(
 577→            "SELECT \
 578→                 tm.id, tm.target_id, tm.raw_transaction_id, tm.match_reason, tm.matched_at, \
 579→                 rt.id AS rt_id, rt.network, rt.tx_hash, rt.timestamp, rt.block_number, \
 580→                 rt.raw_metadata, rt.source, rt.ingestion_run_id, rt.ingested_at \
 581→             FROM target_matches tm \
 582→             JOIN raw_transactions rt ON rt.id = tm.raw_transaction_id \
 583→             WHERE tm.target_id = $1 \
 584→             ORDER BY rt.timestamp DESC \
 585→             LIMIT $2 OFFSET $3",
 586→        )
 587→        .bind(target_id)
 588→        .bind(limit)
 589→        .bind(offset)
 590→        .fetch_all(self.pool())
 591→        .await?;
 592→
 593→        let mut results = Vec::with_capacity(rows.len());
 594→        for row in &rows {
 595→            let tm = TargetMatch {
 596→                id: row.try_get("id")?,
 597→                target_id: row.try_get("target_id")?,
 598→                raw_transaction_id: row.try_get("raw_transaction_id")?,
 599→                match_reason: row.try_get("match_reason")?,
 600→                matched_at: row.try_get("matched_at")?,
 601→            };
 602→            let rt = RawTransaction {
 603→                id: row.try_get("rt_id")?,
 604→                network: row.try_get("network")?,
 605→                tx_hash: row.try_get("tx_hash")?,
 606→                timestamp: row.try_get("timestamp")?,
 607→                block_number: row.try_get("block_number")?,
 608→                raw_metadata: row.try_get("raw_metadata")?,
 609→                source: row.try_get("source")?,
 610→                ingestion_run_id: row.try_get("ingestion_run_id")?,
 611→                ingested_at: row.try_get("ingested_at")?,
 612→            };
 613→            results.push((tm, rt));
 614→        }
 615→        Ok(results)
 616→    }
