    let id = Uuid::new_v4();
    sqlx::query(
        "INSERT INTO index_targets (id, kind, network, chain_family, address, mode, created_at, updated_at)
         VALUES ($1, $2::target_kind_enum, $3, 'solana'::chain_family_enum, $4, 'both'::target_mode_enum, NOW(), NOW())",
    )
    .bind(id)
    .bind(kind)
    .bind(network)
    .bind(address)
    .execute(pool)
    .await
    .unwrap();
    id
}

