#[test]
fn all_target_kinds_covered_by_at_least_one_connector() {
    let all_kinds = [
        TargetKind::Wallet,
        TargetKind::Contract,
        TargetKind::Program,
        TargetKind::Account,
        TargetKind::TopicFilter,
        TargetKind::Market,
